def transform(grid):
    h, w = len(grid), len(grid[0])

    # Identify full-width/full-height separator lines.
    sep_rows = [r for r in range(h) if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r])]
    sep_cols = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    row_ranges = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_ranges = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]

    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row if v != 0 and v not in {grid[r][0] for r in sep_rows}}

    for color in colors:
        occupied = set()
        for ri, (r0, r1) in enumerate(row_ranges):
            for ci, (c0, c1) in enumerate(col_ranges):
                if any(grid[r][c] == color
                       for r in range(r0, r1) for c in range(c0, c1)):
                    occupied.add((ri, ci))
        if len(occupied) < 2:
            continue

        rmin = min(r for r, _ in occupied)
        rmax = max(r for r, _ in occupied)
        cmin = min(c for _, c in occupied)
        cmax = max(c for _, c in occupied)

        if rmin == rmax:
            if rmax + 1 < len(row_ranges):
                rmax += 1
            elif rmin > 0:
                rmin -= 1
        if cmin == cmax:
            if cmax + 1 < len(col_ranges):
                cmax += 1
            elif cmin > 0:
                cmin -= 1

        # Use one existing panel as the canonical pattern, undoing its flips.
        sr, sc = next(iter(occupied))
        sr0, sr1 = row_ranges[sr]
        sc0, sc1 = col_ranges[sc]
        canonical = set()
        for r in range(sr0, sr1):
            for c in range(sc0, sc1):
                if grid[r][c] == color:
                    rr, cc = r - sr0, c - sc0
                    if (sr - rmin) % 2:
                        rr = (sr1 - sr0 - 1) - rr
                    if (sc - cmin) % 2:
                        cc = (sc1 - sc0 - 1) - cc
                    canonical.add((rr, cc))

        for ri in range(rmin, rmax + 1):
            for ci in range(cmin, cmax + 1):
                r0, r1 = row_ranges[ri]
                c0, c1 = col_ranges[ci]
                for rr, cc in canonical:
                    if (ri - rmin) % 2:
                        rr2 = (r1 - r0 - 1) - rr
                    else:
                        rr2 = rr
                    if (ci - cmin) % 2:
                        cc2 = (c1 - c0 - 1) - cc
                    else:
                        cc2 = cc
                    r, c = r0 + rr2, c0 + cc2
                    if r < r1 and c < c1 and out[r][c] == 0:
                        out[r][c] = color

    return out
